What does this program print? Type the line exactly, including the brackets.

```cpp
#include <print>

int main() {
    std::println("[{:>5}|{:<3}|{:^7}]", 42, 7, "mid");
}
```

What does this program print?

```cpp
#include <print>

int main() {
    std::println("{} {} {}", 7 / 2, 7 % 2, 7.0 / 2);
}
```

What number does this program print?

```cpp
#include <print>

int main() {
    int count = 0;
    for (int i = 1; i < 20; i *= 3) {
        ++count;
    }
    std::println("{}", count);
}
```

What does this program print?

```cpp
#include <print>
#include <string>
#include <vector>

int main() {
    std::vector<std::string> names{"Ngozi", "Aiko", "Mateus"};
    names.push_back("Leila");
    std::string longest;
    for (const auto& n : names) {
        if (n.size() > longest.size()) longest = n;
    }
    std::println("{} {}", names.size(), longest);
}
```
